mapper.select:
SELECT AVG(EXTRACT(EPOCH FROM (started_at - e.create_time))/60) as avgStartTime, AVG(EXTRACT(EPOCH FROM (COALESCE(ended_at, CURRENT_TIMESTAMP) - started_at))/60) as avgExecutionTime, AVG(EXTRACT(EPOCH FROM (COALESCE(ended_at, CURRENT_TIMESTAMP) - e.create_time))/60) as avgTotalTime, MIN(EXTRACT(EPOCH FROM (COALESCE(ended_at, CURRENT_TIMESTAMP) - e.create_time))/60) as minResponseTime, MAX(EXTRACT(EPOCH FROM (COALESCE(ended_at, CURRENT_TIMESTAMP) - e.create_time))/60) as maxResponseTime FROM emergency_response r LEFT JOIN emergency_event e ON r.emergency_event_id = e.id WHERE r.deleted = false AND r.status != 'cancelled'
AND e.is_drill = FALSE
AND r.create_time >= #{reqVO.startTime}
AND r.create_time <= #{reqVO.endTime}
AND r.response_level = #{reqVO.responseLevel}
AND e.event_type = #{reqVO.eventType}

SELECT r.response_level as responseLevel, AVG(EXTRACT(EPOCH FROM (r.started_at - e.create_time))/60) as avgStartTime, AVG(EXTRACT(EPOCH FROM (COALESCE(r.ended_at, CURRENT_TIMESTAMP) - r.started_at))/60) as avgExecutionTime, AVG(EXTRACT(EPOCH FROM (COALESCE(r.ended_at, CURRENT_TIMESTAMP) - e.create_time))/60) as avgTotalTime, COUNT(*) as count FROM emergency_response r LEFT JOIN emergency_event e ON r.emergency_event_id = e.id WHERE r.deleted = false AND r.status != 'cancelled'
AND e.is_drill = FALSE
AND r.create_time >= #{reqVO.startTime}
AND r.create_time <= #{reqVO.endTime}
AND e.event_type = #{reqVO.eventType}
GROUP BY r.response_level ORDER BY responseLevel

SELECT e.event_type as eventType, e.event_type as typeName, AVG(EXTRACT(EPOCH FROM (r.started_at - e.create_time))/60) as avgStartTime, AVG(EXTRACT(EPOCH FROM (COALESCE(r.ended_at, CURRENT_TIMESTAMP) - r.started_at))/60) as avgExecutionTime, AVG(EXTRACT(EPOCH FROM (COALESCE(r.ended_at, CURRENT_TIMESTAMP) - e.create_time))/60) as avgTotalTime, COUNT(*) as count FROM emergency_response r LEFT JOIN emergency_event e ON r.emergency_event_id = e.id WHERE r.deleted = false AND r.status != 'cancelled'
AND e.is_drill = FALSE
AND r.create_time >= #{reqVO.startTime}
AND r.create_time <= #{reqVO.endTime}
AND r.response_level = #{reqVO.responseLevel}
GROUP BY e.event_type ORDER BY count DESC

SELECT CASE WHEN total_time <= 10 THEN '0-10分钟' WHEN total_time <= 30 THEN '10-30分钟' WHEN total_time <= 60 THEN '30-60分钟' WHEN total_time <= 120 THEN '1-2小时' WHEN total_time <= 480 THEN '2-8小时' ELSE '8小时以上' END as timeRange, COUNT(*) as count, ROUND(COUNT(*) * 100.0 / SUM(COUNT(*)) OVER (), 2) as percentage FROM ( SELECT EXTRACT(EPOCH FROM (COALESCE(r.ended_at, CURRENT_TIMESTAMP) - e.create_time))/60 as total_time FROM emergency_response r LEFT JOIN emergency_event e ON r.emergency_event_id = e.id WHERE r.deleted = false AND r.status != 'cancelled'
AND e.is_drill = FALSE
AND r.create_time >= #{reqVO.startTime}
AND r.create_time <= #{reqVO.endTime}
AND r.response_level = #{reqVO.responseLevel}
AND e.event_type = #{reqVO.eventType}
) t GROUP BY CASE WHEN total_time <= 10 THEN '0-10分钟' WHEN total_time <= 30 THEN '10-30分钟' WHEN total_time <= 60 THEN '30-60分钟' WHEN total_time <= 120 THEN '1-2小时' WHEN total_time <= 480 THEN '2-8小时' ELSE '8小时以上' END ORDER BY MIN(total_time)

SELECT COUNT(*)
FROM emergency_response r
LEFT JOIN emergency_event e ON r.emergency_event_id = e.id
WHERE r.deleted = false
  AND r.status IN ('ended')

      AND e.is_drill = FALSE


      AND r.create_time >= #{reqVO.startTime}


      AND r.create_time <= #{reqVO.endTime}


      AND r.response_level = #{reqVO.responseLevel}


      AND e.event_type = #{reqVO.eventType}

SELECT COUNT(*)
FROM emergency_response r
LEFT JOIN emergency_event e ON r.emergency_event_id = e.id
WHERE r.deleted = false
  AND r.status != 'cancelled'

      AND e.is_drill = FALSE


      AND r.create_time >= #{reqVO.startTime}


      AND r.create_time <= #{reqVO.endTime}


      AND r.response_level = #{reqVO.responseLevel}


      AND e.event_type = #{reqVO.eventType}

SELECT r.response_level as responseLevel, COUNT(CASE WHEN r.status = 'ended' THEN 1 END) as successCount, COUNT(*) as totalCount, ROUND(COUNT(CASE WHEN r.status = 'ended' THEN 1 END) * 100.0 / COUNT(*), 2) as successRate FROM emergency_response r LEFT JOIN emergency_event e ON r.emergency_event_id = e.id WHERE r.deleted = false AND r.status != 'cancelled'
AND e.is_drill = FALSE
AND r.create_time >= #{reqVO.startTime}
AND r.create_time <= #{reqVO.endTime}
AND e.event_type = #{reqVO.eventType}
GROUP BY r.response_level ORDER BY responseLevel

SELECT e.event_type as eventType, e.event_type as typeName, COUNT(CASE WHEN r.status = 'ended' THEN 1 END) as successCount, COUNT(*) as totalCount, ROUND(COUNT(CASE WHEN r.status = 'ended' THEN 1 END) * 100.0 / COUNT(*), 2) as successRate FROM emergency_response r LEFT JOIN emergency_event e ON r.emergency_event_id = e.id WHERE r.deleted = false AND r.status != 'cancelled'
AND e.is_drill = FALSE
AND r.create_time >= #{reqVO.startTime}
AND r.create_time <= #{reqVO.endTime}
AND r.response_level = #{reqVO.responseLevel}
GROUP BY e.event_type ORDER BY successRate DESC

SELECT h.from_level as fromLevel, h.to_level as toLevel, COUNT(*) as upgradeCount, AVG(EXTRACT(EPOCH FROM (h.create_time - r.started_at))/60) as avgUpgradeTime FROM emergency_response_history h LEFT JOIN emergency_response r ON h.response_id = r.id LEFT JOIN emergency_event e ON r.emergency_event_id = e.id WHERE h.type = 'upgrade' AND r.deleted = false
AND e.is_drill = FALSE
AND h.create_time >= #{reqVO.startTime}
AND h.create_time <= #{reqVO.endTime}
AND h.from_level = #{reqVO.responseLevel}
AND e.event_type = #{reqVO.eventType}
GROUP BY h.from_level, h.to_level ORDER BY upgradeCount DESC

SELECT r.response_level as responseLevel, COUNT(*) as cancelCount FROM emergency_response r LEFT JOIN emergency_event e ON r.emergency_event_id = e.id WHERE r.deleted = false AND r.status = 'cancelled'
AND e.is_drill = FALSE
AND r.create_time >= #{reqVO.startTime}
AND r.create_time <= #{reqVO.endTime}
AND e.event_type = #{reqVO.eventType}
GROUP BY r.response_level ORDER BY cancelCount DESC

SELECT r.response_level as responseLevel, AVG(EXTRACT(EPOCH FROM (COALESCE(r.ended_at, CURRENT_TIMESTAMP) - e.create_time))/60) as avgResponseTime, CASE WHEN r.response_level = 'I' THEN 5 WHEN r.response_level = 'II' THEN 15 WHEN r.response_level = 'III' THEN 30 WHEN r.response_level = 'IV' THEN 60 WHEN r.response_level = 'V' THEN 120 ELSE 60 END as standardTime, ROUND( CASE WHEN r.response_level = 'I' THEN LEAST(100, 100 - (AVG(EXTRACT(EPOCH FROM (COALESCE(r.ended_at, CURRENT_TIMESTAMP) - e.create_time))/60) - 5) / 5 * 20) WHEN r.response_level = 'II' THEN LEAST(100, 100 - (AVG(EXTRACT(EPOCH FROM (COALESCE(r.ended_at, CURRENT_TIMESTAMP) - e.create_time))/60) - 15) / 15 * 20) WHEN r.response_level = 'III' THEN LEAST(100, 100 - (AVG(EXTRACT(EPOCH FROM (COALESCE(r.ended_at, CURRENT_TIMESTAMP) - e.create_time))/60) - 30) / 30 * 20) WHEN r.response_level = 'IV' THEN LEAST(100, 100 - (AVG(EXTRACT(EPOCH FROM (COALESCE(r.ended_at, CURRENT_TIMESTAMP) - e.create_time))/60) - 60) / 60 * 20) WHEN r.response_level = 'V' THEN LEAST(100, 100 - (AVG(EXTRACT(EPOCH FROM (COALESCE(r.ended_at, CURRENT_TIMESTAMP) - e.create_time))/60) - 120) / 120 * 20) ELSE 85 END, 2 ) as efficiencyScore, ROUND( COUNT(CASE WHEN EXTRACT(EPOCH FROM (COALESCE(r.ended_at, CURRENT_TIMESTAMP) - e.create_time))/60 > CASE WHEN r.response_level = 'I' THEN 10 WHEN r.response_level = 'II' THEN 30 WHEN r.response_level = 'III' THEN 60 WHEN r.response_level = 'IV' THEN 120 WHEN r.response_level = 'V' THEN 240 ELSE 120 END THEN 1 END) * 100.0 / COUNT(*), 2 ) as timeoutRate FROM emergency_response r LEFT JOIN emergency_event e ON r.emergency_event_id = e.id WHERE r.deleted = false AND r.status != 'cancelled'
AND e.is_drill = FALSE
AND r.create_time >= #{reqVO.startTime}
AND r.create_time <= #{reqVO.endTime}
AND e.event_type = #{reqVO.eventType}
GROUP BY r.response_level ORDER BY responseLevel
